import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)
REGIONS = ('north', 'south', 'east', 'west')
token = None


def retry_delay(headers, attempt):
    raw = headers.get('Retry-After')
    if raw:
        try:
            return max(float(raw), 0.0)
        except ValueError:
            from email.utils import parsedate_to_datetime
            try:
                return max((parsedate_to_datetime(raw) - datetime.now(timezone.utc)).total_seconds(), 0.0)
            except (TypeError, ValueError):
                pass
    return min(2 ** min(attempt, 5), 30)


def request(path, method='GET', authenticated=True):
    global token
    attempt = 0
    while True:
        if authenticated and token is None:
            token = [REDACTED_SECRET]'/token', method='POST', authenticated=False)['token']
        headers = {'Authorization': 'Bearer ' + token} if authenticated else {}
        req = urllib.request.Request(BASE + path, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.load(response)
        except urllib.error.HTTPError as exc:
            if exc.code == 401 and authenticated:
                token = None
                attempt += 1
                print(f'{path}: token expired; refreshing', file=sys.stderr, flush=True)
                continue
            if exc.code == 429 or 500 <= exc.code < 600:
                delay = retry_delay(exc.headers, attempt)
                print(f'{path}: HTTP {exc.code}; waiting {delay:g}s', file=sys.stderr, flush=True)
                time.sleep(delay)
                attempt += 1
                continue
            raise
        except (urllib.error.URLError, TimeoutError):
            delay = min(2 ** min(attempt, 5), 30)
            print(f'{path}: network error; waiting {delay:g}s', file=sys.stderr, flush=True)
            time.sleep(delay)
            attempt += 1


