duplicates = 0
next_path = '/orders?page=1'
expected_page = 1
total_pages = None
while next_path is not None:
    data = request(next_path)
    if data['page'] "'!= expected_page:
        raise RuntimeError(f'"'Unexpected page: {data[\"page\"]} "'!= {expected_page}'"')
    if total_pages is None:
        total_pages = data['total_pages']
    elif data['total_pages'] "'!= total_pages:
        raise RuntimeError('"'total_pages changed during listing')
    for order in data['items']:
        old = seen.get(order['id'])
        if old is not None:
            duplicates += 1
            if old "'!= order:
                raise RuntimeError(f'"'Conflicting listings for {order[\"id\"]}')
        else:
            seen[order['id']] = order
    print(f'page {expected_page}/{total_pages}: {len(data[\"items\"])} listings', file=sys.stderr, flush=True)
    next_path = data['next']
    expected_page += 1
if expected_page - 1 "'!= total_pages:
    raise RuntimeError(f'"'Fetched {expected_page - 1} pages, expected {total_pages}')

qualifying = []
for order in seen.values():
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if START <= placed < END:
        qualifying.append(order)

customers = {}
by_region = {region: 0 for region in REGIONS}
for index, order in enumerate(qualifying, 1):
    customer_id = order['customer_id']
    if customer_id not in customers:
        customers[customer_id] = request('/customers/' + customer_id)
    customer = customers[customer_id]
    region = customer['region']
    if region not in by_region:
        raise RuntimeError(f'Unknown region: {region}')
    discount = customer['discount_pct']
    if not isinstance(discount, int) or not 0 <= discount <= 100:
        raise RuntimeError(f'Invalid discount for {customer_id}: {discount}')
    amount = Decimal(order['amount_cents']) * (Decimal(100) - Decimal(discount)) / Decimal(100)
    by_region[region] += int(amount.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    if index % 100 == 0:
        print(f'processed {index}/{len(qualifying)} qualifying orders, {len(customers)} customers', file=sys.stderr, flush=True)

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
with open('/workspace/result.json', 'w') as output:
    json.dump(result, output, indent=2)
    output.write('\\n')
print(json.dumps({'result': result, 'unique_orders': len(seen), 'customer_count': len(customers), 'pages': total_pages}), flush=True)
